import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Table, Row, Col, Card, notification } from 'antd'
import FeedBackTableColumns from './constants/feedbackTable'
import FeedBackStyleWrapper from './index.style'
import { get } from 'lodash'
import ReconActions from '../../../../redux/recon/actions'
import QuerySearchBuilder from '../../../../../helpers/querySearchBuilder'
import QueryString from 'query-string'

const { resetReduxStateRecon, reconResolverList } = ReconActions
class FeedBackComponent extends Component {
  state = {
    tableData: [],
    querySearch: {},
    totalRecords: 0
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { reconResolverListData, reconResolverListDataMessage } = nextProps
    if (reconResolverListDataMessage === 'Success') {
      this.setState({
        tableData: get(reconResolverListData, 'data', []),
        totalRecords: get(reconResolverListData, 'meta.total', 0)
      })
      this.props.resetReduxStateRecon(['reconResolverListDataMessage'])
    }
    if (reconResolverListDataMessage !== 'Success' && reconResolverListDataMessage !== undefined) {
      notification.error({ message: 'Error', description: 'Error in loading Table!!!' })
      this.props.resetReduxStateRecon(['reconResolverListDataMessage'])
    }
  }

  componentDidMount () {
    const querySearch = QueryString.parse(this.props.location.search)
    if (Object.values(querySearch).length > 0) {
      this.fetch(querySearch)
    } else {
      this.fetch()
    }
  }

  handleTableChangeFunction = (pagination, filters, sorter) => {
    const { querySearch } = this.state
    const { history, location } = this.props
    const { pageSize, current } = pagination
    const offset = (current - 1) * pageSize
    const finalFilter = {
      ...querySearch,
      page: current,
      offset: Number(offset),
      limit: Number(pageSize)
    }
    this.setState({
      querySearch: finalFilter
    })
    const queryString = QuerySearchBuilder(finalFilter)
    // const querySearchString = QueryString.stringify(finalFilter)
    history.push({
      pathname: location.pathname,
      search: queryString
    })
    this.setState({
      offset,
      limit: Number(pageSize)
    }, () => this.fetch({
      // reference_id: this.props.match.params.policy_id,
      ...finalFilter
    }))
  }

  detailPage = (val) => {
    const reconId = get(val, 'request_id', '')
    this.props.history.push({
      pathname: `/recon/feedback-detail/${reconId}`,
      state: {
        formName: 'feedback-table'
      }
    })
  }

  fetch = (payload = { limit: 10, offset: 0 }) => {
    const { location, history } = this.props
    const { offset, limit } = payload
    const offsetNumber = payload.offset
    const limitSize = payload.limit
    const queryPage = Number(offsetNumber) || Number(offset)
    const queryLimit = Number(limitSize) || Number(limit)
    const finalQuery = {
      page: get(payload, 'page'),
      offset: Number(queryPage),
      limit: queryLimit,
      ...payload
    }
    // finalQuery
    this.setState({
      querySearch: finalQuery,
      page: Number(get(payload, 'page')),
      limit: queryLimit
    })
    const queryString = QuerySearchBuilder(finalQuery)
    history.push({
      pathname: location.pathname,
      search: queryString
    })
    this.props.reconResolverList({ query: finalQuery })
  }

  render () {
    const { tableData, limit, totalRecords } = this.state
    const { reconResolverListLoading } = this.props
    return (
      <FeedBackStyleWrapper>
        <Row type='flex' justify='center'>
          <Col span={24}>
            <Card>
              <Row type='flex'>
                <Col span={24}>
                  <p className='heading'> Resolver Summary Page </p>
                </Col>
                <Col span={24}>
                  <Table
                    loading={reconResolverListLoading}
                    dataSource={tableData}
                    columns={FeedBackTableColumns.call(this)}
                    pagination={{
                      pageSize: limit,
                      total: totalRecords
                    }}
                    onChange={this.handleTableChangeFunction}
                  />
                </Col>
              </Row>
            </Card>
          </Col>
        </Row>
      </FeedBackStyleWrapper>
    )
  }
}
export default connect(
  state => ({
    reconResolverListData: state.Recon.reconResolverListData,
    reconResolverListDataMessage: state.Recon.reconResolverListDataMessage,
    reconResolverListLoading: state.Loading.RECON_RESOLVER_LIST,
    reconResolverListError: state.Error.RECON_RESOLVER_LIST
  }),
  {
    reconResolverList,
    resetReduxStateRecon
  }
)(FeedBackComponent)
