import React from "react";
import { get } from "lodash";
import { FieldDataCodes } from "./feedbackDetail";
export default function FeedBackTableColumns() {
  return [
    {
      title: "Actions",
      render: (val, record) => {
        const detailView = get(val, "state") !== "SUCCESS";
        return detailView ? (
          <i
            className="far fa-eye"
            onClick={() => this.detailPage(val)}
            style={{
              cursor: "pointer",
              textAlign: "center",
            }}
          />
        ) : (
          "-"
        );
      },
    },
    {
      title: "Recon Id",
      dataIndex: "recon_id",
      key: "recon_id",
    },
    {
      title: "Month-Year",
      render: (val) => {
        return `${val.month}-${val.year}`;
      },
    },
    {
      title: "Package",
      dataIndex: "package",
      key: "package",
    },
    {
      title: "Partner",
      dataIndex: "partner",
      key: "partner",
    },
    {
      title: "Product",
      dataIndex: "product_key",
      key: "product_key",
    },
    {
      title: "Missing Pasarpolis",
      dataIndex: FieldDataCodes.missing_in_pp,
      key: FieldDataCodes.missing_in_pp,
    },
    {
      title: "Missing in Partner",
      dataIndex: FieldDataCodes.missing_in_partner,
      key: FieldDataCodes.missing_in_partner,
    },
    {
      title: "Premium Mismatch",
      dataIndex: FieldDataCodes.premium_mismatch,
      key: FieldDataCodes.premium_mismatch,
    },
    {
      title: "Status",
      dataIndex: "state",
      key: "state",
    },
  ];
}
